/// How a function is executed.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum Execution {
    /// By [`crate::scalar::bind_scalar`] under the function's name.
    Scalar,
    /// By this aggregate of the executor.
    Aggregate(Aggregate),
    /// By the expression evaluator itself, like the canonical operators:
    /// the conditionals, which evaluate their arguments lazily
    /// (`krishiv_kernels::conditional`).
    Evaluator,
    /// By the executor's window operator, over a window (`row_number`,
    /// `rank`, ...); never called without `OVER`.
    Window,
    /// By the executor's higher-order compiler, which evaluates the lambda
    /// bodies: `transform`, `filter`, `exists`, `forall`, `aggregate`,
    /// `reduce`, `zip_with`, `map_filter`, `map_zip_with`, `transform_keys`,
    /// `transform_values` and `array_sort`
    /// (`krishiv_exec::planner::eval::hof`, over `krishiv_kernels::list` and
    /// `krishiv_kernels::map`). A lambda is no Arrow value, so these never
    /// bind a kernel here.
    HigherOrder,
    /// Rewritten to a `CAST` during analysis (the cast-named functions:
    /// `float(x)`, `int(x)`, ...); the plan only ever holds the `Cast`
    /// node, so this is never executed and never bound.
    Cast,
    /// Lowered to a `Generate` node (`explode`, `posexplode`, `inline` and
    /// their `_outer` forms); the plan never holds the call, so this is
    /// never bound.
    Generator,
}

/// The aggregates the executor implements.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum Aggregate {
    /// `count`.
    Count,
    /// `sum`.
    Sum,
    /// `avg` / `mean`.
    Avg,
    /// `min`.
    Min,
    /// `max`.
    Max,
    /// `first` / `first_value`; `ignoreNulls` is the second argument.
    First,
    /// `last` / `last_value`; `ignoreNulls` is the second argument.
    Last,
    /// `stddev` / `std` / `stddev_samp`.
    StddevSamp,
    /// `stddev_pop`.
    StddevPop,
    /// `variance` / `var_samp`.
    VarSamp,
    /// `var_pop`.
    VarPop,
    /// `skewness`.
    Skewness,
    /// `kurtosis`.
    Kurtosis,
    /// `corr`.
    Corr,
    /// `covar_samp`.
    CovarSamp,
    /// `covar_pop`.
    CovarPop,
    /// `any_value`; `ignoreNulls` is the second argument.
    AnyValue,
    /// `max_by(x, y)`.
    MaxBy,
    /// `min_by(x, y)`.
    MinBy,
    /// `collect_list(x)` (and `array_agg`, which the analyzer resolves as
    /// `collect_list` for Spark's display name).
    CollectList,
    /// `collect_set(x)`.
    CollectSet,
    /// `vector_sum(x)`: element-wise sums over `ARRAY<FLOAT>`.
    VectorSum,
    /// `vector_avg(x)`: element-wise means over `ARRAY<FLOAT>`.
    VectorAvg,
    /// `bit_and(x)`: the bitwise AND of the non-NULL `TINYINT` ..
    /// `BIGINT` values; NULL for no non-NULL value. The input type.
    BitAnd,
    /// `bit_or(x)`, as `bit_and` for OR.
    BitOr,
    /// `bit_xor(x)`, as `bit_and` for XOR.
    BitXor,
    /// `regr_count(y, x)`: the number of rows where both are non-NULL.
    /// `bigint`, never NULL.
    RegrCount,
    /// `regr_avgx(y, x)`: the mean of `x` over non-NULL pairs. `double`.
    RegrAvgx,
    /// `regr_avgy(y, x)`: the mean of `y` over non-NULL pairs. `double`.
    RegrAvgy,
    /// `regr_sxx(y, x)`: `n * var_pop(x)` over non-NULL pairs. `double`.
    RegrSxx,
    /// `regr_syy(y, x)`: `n * var_pop(y)` over non-NULL pairs. `double`.
    RegrSyy,
    /// `regr_sxy(y, x)`: `n * covar_pop(y, x)` over non-NULL pairs.
    /// `double`.
    RegrSxy,
    /// `regr_slope(y, x)`: the slope of the regression line; NULL when
    /// `x` does not vary. `double`.
    RegrSlope,
    /// `regr_intercept(y, x)`: the intercept of the regression line.
    /// `double`.
    RegrIntercept,
    /// `regr_r2(y, x)`: the coefficient of determination; NULL when `x`
    /// does not vary, 1 when only `y` does not. `double`.
    RegrR2,
    /// `mode(col)`: the most frequent non-NULL value (ties broken as
    /// Spark breaks them); the analyzer types the `mode(col,
    /// deterministic)` and `mode() WITHIN GROUP (ORDER BY col)` forms.
    /// The input type.
    Mode,
    /// `listagg(expr[, delimiter])` (and `string_agg`, which the analyzer
    /// resolves as `listagg` for Spark's display name): the non-NULL
    /// values joined by the delimiter. The input type (`STRING` or
    /// `BINARY`), NULL for no value.
    ListAgg,
    /// `try_sum(x)`: `sum` that gives NULL instead of an overflow error.
    TrySum,
    /// `try_avg(x)`: `avg` that gives NULL instead of an overflow error.
    TryAvg,
    /// `percentile(x, percentage[, frequency])`: the exact percentiles; the
    /// analyzer folds the percentages into the execution form.
    Percentile,
    /// `percentile_approx(x, percentage[, accuracy])` /
    /// `approx_percentile`: Spark's Greenwald-Khanna summary.
    PercentileApprox,
    /// `median(x)`: `percentile(x, 0.5)`.
    Median,
    /// `percentile_cont(percentage) WITHIN GROUP (ORDER BY x)`.
    PercentileCont,
    /// `percentile_disc(percentage) WITHIN GROUP (ORDER BY x)`.
    PercentileDisc,
    /// `approx_count_distinct(x[, relativeSD])`: HyperLogLog++.
    ApproxCountDistinct,
}

/// A built-in function.
#[non_exhaustive]
pub struct FunctionDef {
    /// The name (lower case), as Spark lists it; an alias is its own entry.
    pub name: &'static str,
    /// A handle for this process (the definition's position); never part
    /// of a plan key.
    pub id: u32,
    /// Scalar, aggregate, ...
    pub kind: FunctionKind,
    /// Whether Spark analyzes a call as deterministic.
    pub deterministic: bool,
    /// The oldest release line that has it.
    pub since: SparkProfile,
    /// The argument counts it takes.
    pub arity: Arity,
    /// How its arguments are implicitly cast.
    pub inputs: Inputs,
    /// Its result type for the (cast) argument types.
    pub result: ResultType,
    /// How it runs.
    pub execution: Execution,
}

impl fmt::Debug for FunctionDef {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("FunctionDef")
            .field("name", &self.name)
            .field("id", &self.id)
            .field("kind", &self.kind)
            .field("deterministic", &self.deterministic)
            .field("since", &self.since)
            .field("arity", &self.arity)
            .field("inputs", &self.inputs)
            .field("execution", &self.execution)
            .finish_non_exhaustive()
    }
}

/// A registry lookup.
#[derive(Debug, Clone, Copy)]
#[non_exhaustive]
pub enum Lookup<'a> {
    /// Found.
    Found(&'a FunctionDef),
    /// Spark has it in this profile but Krishiv does not implement it.
    KnownUnsupported,
    /// Spark does not have it in this profile.
    NotFound,
}

/// The built-in functions.
#[derive(Debug)]
pub struct Registry {
    defs: HashMap<&'static str, FunctionDef>,
    spark: HashMap<&'static str, SparkFunction>,
    /// Definitions without a catalog row (a registry bug; the tests check
    /// there are none). They are not registered.
    unlisted: Vec<&'static str>,
}

/// The process-wide registry.
static BUILTINS: LazyLock<Registry> = LazyLock::new(Registry::build);

/// The built-in function registry.
#[must_use]
pub fn builtins() -> &'static Registry {
    &BUILTINS
}

/// Whether `name` is one Spark's grammar owns (`TIMESTAMPADD` and `TIMESTAMPDIFF`): it has
/// a definition but no row in Spark's function catalog, and the lowering
/// reaches it through the keyword-unit forms. A call spelled as an ordinary
/// function (`timestampadd(col, 1, ts)`) also resolves here, where Spark says
/// `UNRESOLVED_ROUTINE`: a known divergence.
#[must_use]
pub fn is_grammar_only(name: &str) -> bool {
    grammar_row(name).is_some()
}

/// The catalog row of a name Spark's grammar owns: `TIMESTAMPADD` and
/// `TIMESTAMPDIFF` (and the unit forms of `DATEADD`/`DATEDIFF` the lowering
/// renames to them) are parsed into expressions, not registered in Spark.
/// Three arguments, as the grammar takes.
fn grammar_row(name: &str) -> Option<SparkFunction> {
    let name = match name {
        "timestampadd" => "timestampadd",
        "timestampdiff" => "timestampdiff",
        // `base[index]`: the lowering of a subscript (Spark's `ExtractValue`).
        "__subscript" => "__subscript",
        _ => return None,
    };
    let arity = if name == "__subscript" {
        Arity::new([false, false, true, false, false, false, false], "2")
    } else {
        Arity::new([false, false, false, true, false, false, false], "3")
    };
    Some(SparkFunction {
        name,
        registry: "function",
        since: SparkProfile::V3_5,
        deterministic: Some(true),
        kind: Some(FunctionKind::Scalar),
        arity,
    })
}

impl Registry {
    fn build() -> Self {
        let (rows, _) = catalog::load();
        let spark: HashMap<&'static str, SparkFunction> =
            rows.into_iter().map(|r| (r.name, r)).collect();
        let mut defs = HashMap::new();
        let mut unlisted = Vec::new();
        for (id, spec) in (0_u32..).zip(defs::specs()) {
            let grammar = grammar_row(spec.name);
            let Some(row) = spark.get(spec.name).or(grammar.as_ref()) else {
                unlisted.push(spec.name);
                continue;
            };
            defs.insert(
                spec.name,
                FunctionDef {
                    name: spec.name,
                    id,
                    kind: spec.kind,
                    // A function Spark rejects in every probe is taken as
                    // nondeterministic: the optimizer then never moves it.
                    deterministic: row.deterministic.unwrap_or(false),
                    since: row.since,
                    arity: row.arity.clone(),
                    inputs: spec.inputs,
                    result: Arc::new(spec.result),
                    execution: spec.execution,
                },
            );
        }
        Self {
            defs,
            spark,
            unlisted,
        }
    }

    /// The function `name` (ASCII case-insensitive) in `profile`.
    #[must_use]
    pub fn lookup(&self, name: &str, profile: SparkProfile) -> Lookup<'_> {
        let lower = name.to_ascii_lowercase();
        if let Some(def) = self.defs.get(lower.as_str()) {
            return if profile >= def.since {
                Lookup::Found(def)
            } else {
                Lookup::NotFound
            };
        }
        match self.spark.get(lower.as_str()) {
            Some(s) if profile >= s.since => Lookup::KnownUnsupported,
            _ => Lookup::NotFound,
        }
    }

    /// Every implemented function, sorted by name.
    #[must_use]
    pub fn functions(&self) -> Vec<&FunctionDef> {
        let mut out: Vec<&FunctionDef> = self.defs.values().collect();
        out.sort_unstable_by_key(|d| d.name);
        out
    }

    /// Spark's catalog entry for `name` (lower case).
    #[must_use]
    pub fn spark_function(&self, name: &str) -> Option<&SparkFunction> {
        self.spark.get(name)
    }

    /// The number of names in Spark's catalog (all release lines).
    #[must_use]
    pub fn spark_function_count(&self) -> usize {
        self.spark.len()
    }

    /// Definitions whose name Spark's catalog does not have; they are not
    /// registered (empty unless a definition is misnamed).
    #[must_use]
    pub fn unlisted(&self) -> &[&'static str] {
        &self.unlisted
    }

    /// Changes whenever a lookup could answer differently; the built-ins
    /// are fixed per build.
    #[must_use]
    pub const fn version(&self) -> u64 {
        0
    }
}

